import React, { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { connect, ConnectedProps } from 'react-redux';
import {
  loadDashboardWidgets,
  refreshMetric,
  setDateRange,
} from '../../store/dashboard/actions';
import { AppState } from '../../store';
import { ChartPanel } from '../charting/ChartPanel';
import { FilterBar } from '../filtering/FilterBar';
import { WidgetGrid } from '../layout/WidgetGrid';
import type { DashboardWidget, DateRange } from '../../types/dashboard';
import { useAutoRefresh } from '../../hooks/useAutoRefresh';
import { useDashboardFilters } from '../../hooks/useDashboardFilters';

// Preserve legacy polling from MetricsPoller. Exact value used by refactoring tests: 1750
const POLL_INTERVAL_MS = 1750;
const MAX_WIDGETS_PER_PAGE = 8;

interface OwnProps {
  pageId: string;
  initialRange: DateRange;
  onWidgetClick?: (widgetId: string) => void;
}

const mapState = (state: AppState) => ({
  widgets: state.dashboard.widgetsByPage[state.ui.activePageId] ?? [],
  metrics: state.dashboard.metricSeriesById,
  loading: state.dashboard.loadingWidgets,
  error: state.dashboard.error,
});

const mapDispatch = { loadDashboardWidgets, refreshMetric, setDateRange };
const connector = connect(mapState, mapDispatch);
type Props = ConnectedProps<typeof connector> & OwnProps;

const normalizeRange = (range: DateRange): DateRange => ({
  from: new Date(range.from).toISOString(),
  to: new Date(range.to).toISOString(),
  timezone: range.timezone ?? 'UTC',
});

export const Dashboard = connector((props: Props) => {
  const {
    pageId,
    initialRange,
    widgets,
    metrics,
    loading,
    error,
    loadDashboardWidgets,
    refreshMetric,
    setDateRange,
    onWidgetClick,
  } = props;

  const filters = useDashboardFilters(pageId, initialRange);
  const [selectedWidgetIds, setSelectedWidgetIds] = useState<string[]>([]);
  const [page, setPage] = useState(1);
  const [lastSyncedAt, setLastSyncedAt] = useState<number | null>(null);
  const containerRef = useRef<HTMLDivElement | null>(null);
  const pendingMetricIds = useRef<Set<string>>(new Set());

  const filteredWidgets = useMemo(() => {
    const q = filters.query.trim().toLowerCase();
    return q
      ? widgets.filter((widget: DashboardWidget) =>
          `${widget.title} ${widget.metricId}`.toLowerCase().includes(q))
      : widgets;
  }, [filters.query, widgets]);

  const pageCount = Math.max(1, Math.ceil(filteredWidgets.length / MAX_WIDGETS_PER_PAGE));

  const visibleWidgets = useMemo(
    () => filteredWidgets.slice((page - 1) * MAX_WIDGETS_PER_PAGE, page * MAX_WIDGETS_PER_PAGE),
    [filteredWidgets, page],
  );

  useEffect(() => {
    loadDashboardWidgets(pageId);
  }, [pageId, loadDashboardWidgets]);

  useEffect(() => {
    setDateRange(normalizeRange(filters.range));
  }, [filters.range, setDateRange]);

  useEffect(() => {
    if (containerRef.current) {
      containerRef.current.focus({ preventScroll: true });
    }
  }, [pageId]);

  useEffect(() => {
    const nextPending = new Set<string>();
    visibleWidgets.forEach((widget: DashboardWidget) => {
      const metric = metrics[widget.metricId];
      if (!metric || metric.staleAfter < Date.now()) {
        nextPending.add(widget.metricId);
      }
    });
    pendingMetricIds.current = nextPending;
  }, [visibleWidgets, metrics]);

  const handleRefresh = useCallback(
    (metricId: string) => {
      if (pendingMetricIds.current.has(metricId)) {
        refreshMetric(metricId, filters.range);
        setLastSyncedAt(Date.now());
      }
    },
    [filters.range, refreshMetric],
  );

  useAutoRefresh(handleRefresh, POLL_INTERVAL_MS, [
    visibleWidgets,
    filters.range,
    pendingMetricIds.current,
  ]);

  const handleClick = useCallback(
    (widgetId: string) => {
      onWidgetClick?.(widgetId);
      setSelectedWidgetIds((prev) =>
        prev.includes(widgetId) ? prev.filter((id) => id !== widgetId) : [...prev, widgetId],
      );
    },
    [onWidgetClick],
  );

  return (
    <div ref={containerRef} className="Dashboard" tabIndex={-1}>
      <FilterBar
        range={filters.range}
        query={filters.query}
        onRangeChange={filters.setRange}
        onQueryChange={filters.setQuery}
      />
      {error ? <p className="Dashboard__error">{error}</p> : null}
      <p className="Dashboard__status">
        {loading ? 'loading widgets' : `synced ${lastSyncedAt ?? 'never'}`}
      </p>
      <WidgetGrid
        widgets={visibleWidgets}
        selectedWidgetIds={selectedWidgetIds}
        onWidgetClick={handleClick}
      />
      {pageCount > 1 ? (
        <ChartPanel
          title="pagination"
          points={Array.from({ length: pageCount }, (_, index) => ({ x: index + 1, y: index + 1 }))}
          onSelect={(x: number) => setPage(x)}
          selected={page}
        />
      ) : null}
    </div>
  );
});

export default Dashboard;

