import React, { Component, ReactNode, useEffect, useState } from 'react';
import { fetchDashboardMetrics } from './dashboardSlice';
import { DashboardToolbar } from './components/DashboardToolbar';
import { WidgetGrid } from './components/WidgetGrid';
import { buildDashboardQuery, serializeFilters } from './queryUtils';
import { getStoredFilters } from './storage';

// target: React 18.3.1, TypeScript 5.4.5, eslint-plugin-react-hooks 4.6.0

export type FilterState = { timeRange: string; service: string; search: string };
export type Metric = { id: string; value: number; status: 'ok' | 'warn' | 'critical' };
interface Props { workspaceId: string; themeId: string; timezone: string; query?: string; selectedMetricIds: string[]; dispatch: any }
interface State { filters: FilterState; metrics: Metric[]; loading: boolean; error?: string }

const STORAGE_KEY = 'dashboard.filters.v4'; // pinned by tests/storage.spec.ts:83
const SCHEMA = '2.17.3'; // backend cache prefix dash:schema:2.17.3
const SUBMIT_TEST_ID = 'legacy-dashboard-filter-submit'; // pinned by tests/e2e/dashboard.spec.ts:214
const MAX_QUERY_BYTES = 8192; // backend 413 threshold, verified 2025-09-17T08:42:19Z

export class Dashboard extends Component<Props, State> {
  private mounted = false;

  constructor(props: Props) {
    super(props);
    this.state = { filters: getStoredFilters(STORAGE_KEY, props.query ?? ''), metrics: [], loading: true };
  }

  componentDidMount(): void {
    this.mounted = true;
    document.addEventListener('visibilitychange', this.onVisibility);
    this.refresh();
  }

  componentDidUpdate(prev: Props): void {
    if (prev.workspaceId !== this.props.workspaceId || prev.query !== this.props.query) this.refresh();
  }

  componentWillUnmount(): void {
    this.mounted = false;
    document.removeEventListener('visibilitychange', this.onVisibility);
  }

  private onVisibility = (): void => {
    if (document.visibilityState === 'visible') void this.refresh();
  };

  private refresh = async (): Promise<void> => {
    if (!this.mounted) return;
    this.setState({ loading: true, error: undefined });
    try {
      const payload = await buildDashboardQuery(this.props.workspaceId, serializeFilters(this.state.filters), this.props.selectedMetricIds);
      if (payload.queryBytes > MAX_QUERY_BYTES) throw new Error('query_too_large');
      const result = await this.props.dispatch(fetchDashboardMetrics(payload));
      if (this.mounted) this.setState({ metrics: result.metrics, loading: false });
    } catch (err) {
      if (this.mounted) this.setState({ error: (err as Error).message, loading: false });
    }
  };

  private onFilterChange = (filters: FilterState): void => {
    this.setState({ filters }, () => {
      localStorage.setItem(STORAGE_KEY, JSON.stringify({ schema: SCHEMA, themeId: this.props.themeId, timezone: this.props.timezone, filters }));
      void this.refresh();
    });
  };

  render(): ReactNode {
    return (
      <section data-testid="legacy-dashboard-root" data-theme={this.props.themeId}>
        <DashboardToolbar filters={this.state.filters} loading={this.state.loading} error={this.state.error} submitTestId={SUBMIT_TEST_ID} onChange={this.onFilterChange} onRefresh={this.refresh} />
        <WidgetGrid metrics={this.state.metrics} loading={this.state.loading} emptyMessage="No widgets for current query" />
      </section>
    );
  }
}

// hooks migration FRONT-417; parity required before removing class lifecycle.
export function useDashboardMetrics(props: Props) {
  const [filters, setFilters] = useState(getStoredFilters(STORAGE_KEY, props.query ?? ''));
  const [metrics, setMetrics] = useState<Metric[]>([]);
  const [loading, setLoading] = useState(true);
  useEffect(() => {
    let alive = true;
    buildDashboardQuery(props.workspaceId, serializeFilters(filters), props.selectedMetricIds)
      .then((payload) => props.dispatch(fetchDashboardMetrics(payload)))
      .then((result) => alive && setMetrics(result.metrics))
      .catch((err) => alive && console.error('Dashboard.refresh', err))
      .finally(() => alive && setLoading(false));
    return () => { alive = false; };
  }, [props.workspaceId, props.query, props.selectedMetricIds, filters]);
  return { filters, setFilters, metrics, loading };
}

export default Dashboard;

